import re, glob, os
import collections
cat=collections.defaultdict(list)
for p in sorted(glob.glob('corpus/submissions/*.patch')):
    txt=open(p, encoding='utf-8', errors='replace').read()
    files=[m.group(2) for m in re.finditer(r'^diff --git a/(\S+) b/(\S+)', txt, re.M)]
    kind=[]
    if 'pytest.ini' in txt: kind.append('plugin-ini')
    if 'conftest.py' in txt: kind.append('conftest')
    if any(f.startswith('test') or '/test' in f or f.endswith('tests.md') for f in files): kind.append('testfiles:'+",".join(f for f in files if f.startswith('test') or '/test' in f or f.endswith('.md')))
    if not kind: kind.append('clean')
    cat[" + ".join(kind)].append(os.path.basename(p))
for k,v in cat.items():
    print("==",k, len(v))
    for n in v[:4]: print("   ", n)
EOF

