        print(f"{rid}: INSTANCE NOT FOUND"); continue
    statuses = {}
    for line in log_path.read_text(errors="replace").splitlines():
        m = PROG.match(line)
        if m: statuses[m.group("node")] = m.group("status")
    required = list(inst.get("fail_to_pass", [])) + list(inst.get("pass_to_pass", []))
    missing = [n for n in required if n not in statuses]
    failed  = [n for n in required if n in statuses and statuses[n] not in ("PASSED", "XPASS")]
    verdict = "RESOLVED" if not missing and not failed else ("UNRESOLVED" if not missing else f"MISSING({len(missing)})")
    print(f"{rid}: required={len(required)} statuses={len(statuses)} -> {verdict}")
    for n in missing[:4]: print(f"    missing: {n}")
    for n in failed[:4]:  print(f"    failed:  {n} [{statuses[n]}]")
EOF

