import json, re
from pathlib import Path
C = Path("corpus")
new = {}
for line in open("/tmp/repair_check/regrade.jsonl"):
    if line.strip():
        d = json.loads(line); new[d["record_id"]] = d
inst = {}
for line in open(C/"manifest.jsonl"):
    if line.strip():
        d = json.loads(line); inst[d["instance_id"]] = d

def targets(rid):
    p = C/"submissions"/f"{rid}.patch"
    t = p.read_text() if p.exists() else ""
    return re.findall(r"^\+\+\+ b/(.+)$", t, re.M)

